"""Build 35 «الإحساس»: جودة الرسوميات (تلقائي/عالية/منخفضة)، عدّادات الأرقام ووهج ارتفاع التقييم، اتجاه انتقال التبويبات، أصوات الواجهة،
Haptics الأصلي مع احتياطي navigator.vibrate، وأصوات المشاهد الجديدة. (Chromium فقط — ليس جهاز أندرويد حقيقيًا ولا Haptics حقيقيًا.)"""
from common import *
with sync_playwright() as p:
    b = p.chromium.launch(args=['--no-sandbox'])
    ctx = b.new_context(viewport={'width': 390, 'height': 844}, locale='ar'); page = ctx.new_page(); page.set_default_timeout(30000); attach_errors(page)
    new_game(page, club='ath', pos='CM', age=21, seed=12); play_weeks(page, 3)
    # 1) الجودة
    check(ev(page, "G.UI.qualityPref()") == 'auto', 'الافتراضي تلقائي')
    for q in ['low', 'high']:
        ev(page, "G.UI.prefs.quality='%s'; G.UI.applyQuality()" % q)
        check(ev(page, "document.documentElement.getAttribute('data-q')") == q, 'data-q=%s' % q)
    ev(page, "G.UI.prefs.quality='auto'; G.UI.applyQuality()")
    check(ev(page, "document.documentElement.getAttribute('data-q')") == ev(page, "G.UI.quality()"), 'تلقائي يطابق الكشف')
    ev(page, "G.UI.cur='settings'; G.UI.render()"); page.wait_for_timeout(200)
    check(len(page.query_selector_all('[data-a="qualitySet"]')) == 3, 'ثلاثة خيارات جودة في الإعدادات')
    page.click('[data-a="qualitySet"][data-v="low"]'); page.wait_for_timeout(200)
    check(ev(page, "G.UI.prefs.quality") == 'low' and ev(page, "document.documentElement.getAttribute('data-q')") == 'low', 'اختيار «منخفضة» يُطبَّق ويُحفظ')
    check(ev(page, "JSON.parse(localStorage.getItem(Object.keys(localStorage).find(k=>/pref/i.test(k))||'')||'{}').quality") == 'low', 'الخيار محفوظ في تفضيلات الجهاز')
    check(ev(page, "G.UI.motionOK()") is False, 'الحركات الزمنية معطّلة بالجودة المنخفضة')
    check(page.query_selector('[data-a="prefToggle"][data-v="uiSound"]') is not None and page.query_selector('[data-a="prefToggle"][data-v="scenes"]') is not None, 'مفاتيح أصوات الواجهة والمشاهد في الإعدادات')
    page.click('[data-a="qualitySet"][data-v="high"]'); page.wait_for_timeout(150)
    # 2) الأتمتة تعطّل الحركة الزمنية ما لم تُفعَّل صراحةً
    check(ev(page, "G.UI.motionOK()") is False, 'تحت الأتمتة (webdriver) لا حركة زمنية افتراضيًا')
    ev(page, "G.UI.prefs.motionTest=true")
    check(ev(page, "G.UI.motionOK()") is True, 'التفعيل الصريح يشغّل الحركة (للاختبار)')
    # 3) العدّاد
    ev(page, "window.__e=document.createElement('b');document.body.appendChild(window.__e);G.UI.countTo(window.__e,0,87,300)"); page.wait_for_timeout(120)
    mid = int(ev(page, "window.__e.textContent")); page.wait_for_timeout(450)
    check(0 <= mid < 87 and ev(page, "window.__e.textContent") == '87', 'العدّاد يتحرك ثم يستقر على القيمة النهائية (وسطي=%d)' % mid)
    ev(page, "G.UI.countTo(window.__e,5.0,7.3,200)"); page.wait_for_timeout(450)
    check(ev(page, "window.__e.textContent") == '7.3', 'عدّاد عشري ينتهي بالقيمة بدقة')
    # 4) وهج ارتفاع التقييم
    ev(page, "G.UI.cur='home'; G.UI.render()"); page.wait_for_timeout(1200)
    o = ev(page, "G.S.players[G.S.user].ovr")
    ev(page, "G.S.players[G.S.user].ovr += 3; G.UI.render()"); page.wait_for_timeout(250)
    check(ev(page, "!!document.querySelector('.cine-ovr .ovr.cu-up')") and ev(page, "(document.querySelector('.cu-d')||{}).textContent") == '+3', 'ارتفاع التقييم: وهج + شارة +3')
    page.wait_for_timeout(1200)
    check(ev(page, "document.querySelector('.cine-ovr .ovr').textContent") == str(o + 3), 'الرقم النهائي صحيح بعد العدّ (%d)' % (o + 3))
    # 5) اتجاه الانتقال
    ev(page, "G.UI.cur='home'; G.UI.render(); G.UI.cur='league'; G.UI.render()")
    check(ev(page, "/dir-[lr]/.test(document.getElementById('app').className)"), 'انتقال بين مجموعتين يضيف اتجاهًا')
    ev(page, "G.UI.cur='league'; G.UI.render()")
    # 6) الجودة المنخفضة تلغي حركة الدخول فعليًا
    ev(page, "G.UI.prefs.quality='low'; G.UI.applyQuality(); G.UI.cur='home'; G.UI.render()")
    check(ev(page, "getComputedStyle(document.querySelector('#app > *')).animationName") == 'none', 'جودة منخفضة: لا حركة دخول للعناصر')
    ev(page, "G.UI.prefs.quality='high'; G.UI.applyQuality()")
    # 7) أصوات الواجهة
    ev(page, "window.__snd=[];const _p=G.Audio.play;G.Audio.play=function(n){window.__snd.push(n);return _p.apply(this,arguments)}; G.UI.prefs.sound=true; G.UI.prefs.uiSound=true")
    ev(page, "G.UI.cur='home'; G.UI.render()"); page.wait_for_timeout(200)
    page.click('#bottomnav [data-a]:not(.on)') if page.query_selector('#bottomnav [data-a]:not(.on)') else page.click('.bottomnav button:not(.on)'); page.wait_for_timeout(250)
    check('nav' in ev(page, "window.__snd"), 'نقر التنقل السفلي يُصدر صوت nav (%s)' % ev(page, "window.__snd"))
    ev(page, "window.__snd.length=0; G.UI.prefs.uiSound=false")
    page.click('.bottomnav button:not(.on)'); page.wait_for_timeout(200)
    check('nav' not in ev(page, "window.__snd") and 'tap' not in ev(page, "window.__snd"), 'إيقاف أصوات الواجهة يكتمها')
    ev(page, "G.UI.prefs.uiSound=true")
    # 8) الاهتزاز: أصلي إن وُجد، وإلا navigator.vibrate
    ev(page, "G.UI.prefs.haptics=true; window.__v=[]; navigator.vibrate=(p)=>{window.__v.push(p);return true}")
    check(ev(page, "G.Audio.vibe('goalMe')") is True and len(ev(page, "window.__v")) == 1, 'بلا Haptics أصلي: navigator.vibrate يُستعمل')
    ev(page, "window.__h=[];window.Capacitor={isNativePlatform:()=>true,Plugins:{Haptics:{impact:(o)=>window.__h.push('i:'+o.style),notification:(o)=>window.__h.push('n:'+o.type)}}}; window.__v.length=0")
    ev(page, "G.Audio.vibe('nav'); G.Audio.vibe('level'); G.Audio.vibe('bad'); G.Audio.vibe('card')")
    check(ev(page, "window.__h") == ['i:LIGHT', 'n:SUCCESS', 'n:ERROR', 'i:MEDIUM'], 'Haptics الأصلي: ربط الأنماط (%s)' % ev(page, "window.__h"))
    check(len(ev(page, "window.__v")) == 0, 'مع Haptics الأصلي لا يُستدعى navigator.vibrate')
    ev(page, "window.__h.length=0; G.Audio.vibe('trophy')"); page.wait_for_timeout(700)
    check(len(ev(page, "window.__h")) >= 3, 'نمط الكأس يُنفَّذ نبضات متتابعة (%d)' % len(ev(page, "window.__h")))
    ev(page, "window.Capacitor={isNativePlatform:()=>true,Plugins:{Haptics:{impact(){throw new Error('x')},notification(){throw new Error('x')}}}}; window.__v.length=0")
    check(ev(page, "G.Audio.vibe('goalMe')") is True and len(ev(page, "window.__v")) == 1, 'فشل الأصلي يرجع للاحتياطي دون كسر')
    ev(page, "window.Capacitor={isNativePlatform:()=>true,Plugins:{Haptics:{impact:()=>Promise.reject(new Error('unimpl')),notification:()=>Promise.reject(new Error('unimpl'))}}}")
    ev(page, "G.Audio.vibe('nav'); G.Audio.vibe('level'); G.Audio.vibe('stamp'); G.Audio.vibe('trophy')"); page.wait_for_timeout(800)
    check(not errors, 'رفض وعد Haptics (غير منفَّذ) لا يظهر كخطأ غير ملتقَط: %s' % errors[:2])
    ev(page, "window.Capacitor={isNativePlatform:()=>true,Plugins:{Haptics:{}}}; window.__v.length=0")
    check(ev(page, "G.Audio.vibe('nav')") is True and len(ev(page, "window.__v")) == 1, 'إضافة بلا دوال → احتياطي navigator.vibrate')
    ev(page, "window.__h=[];window.Capacitor={isNativePlatform:()=>true,Plugins:{Haptics:{impact:(o)=>window.__h.push('i:'+o.style),notification:(o)=>window.__h.push('n:'+o.type)}}}; G.Audio.vibe('stamp')")
    check(ev(page, "window.__h") == ['i:HEAVY'], 'stamp = نبضة ثقيلة واحدة (%s)' % ev(page, "window.__h"))
    # بلا Capacitor.Plugins.Haptics (تطبيق بلا حزمة JS): وكيل عبر registerPlugin، مرة واحدة ومخزَّن
    ev(page, "window.__h=[];window.__reg=0;window.Capacitor={isNativePlatform:()=>true,isPluginAvailable:()=>true,Plugins:{},registerPlugin:(n)=>{window.__reg++;return {impact:(o)=>window.__h.push(n+':i:'+o.style),notification:(o)=>window.__h.push(n+':n:'+o.type)}}}; window.__v.length=0")
    ev(page, "G.Audio.vibe('nav'); G.Audio.vibe('level'); G.Audio.vibe('nav')")
    check(ev(page, "window.__h") == ['Haptics:i:LIGHT', 'Haptics:n:SUCCESS', 'Haptics:i:LIGHT'] and ev(page, "window.__reg") == 1 and len(ev(page, "window.__v")) == 0, 'registerPlugin("Haptics") يُستعمل مرة واحدة ومخزَّنًا (%s, reg=%s)' % (ev(page, "window.__h"), ev(page, "window.__reg")))
    ev(page, "window.__h.length=0;window.Capacitor={isNativePlatform:()=>true,isPluginAvailable:()=>false,Plugins:{},registerPlugin:()=>({impact:(o)=>window.__h.push('x'),notification:()=>window.__h.push('x')})}; window.__v.length=0")
    check(ev(page, "G.Audio.vibe('nav')") is True and ev(page, "window.__h") == [] and len(ev(page, "window.__v")) == 1, 'الإضافة غير مثبّتة (isPluginAvailable=false) ⇒ احتياطي navigator.vibrate')
    ev(page, "window.Capacitor={isNativePlatform:()=>false,Plugins:{Haptics:{impact:()=>window.__h.push('y')}}}; window.__v.length=0; window.__h.length=0")
    check(ev(page, "G.Audio.vibe('nav')") is True and ev(page, "window.__h") == [] and len(ev(page, "window.__v")) == 1, 'متصفح عادي (غير أصلي) حتى لو وُجد Capacitor ⇒ navigator.vibrate')
    ev(page, "delete window.Capacitor; G.UI.prefs.haptics=false; window.__v.length=0; G.Audio.vibe('goalMe')")
    check(len(ev(page, "window.__v")) == 0, 'إيقاف الاهتزاز يمنعه')
    # 9) الأصوات الجديدة لا ترمي (مع السياق الصوتي) ولها صدى بالجودة العالية فقط
    ev(page, "G.UI.prefs.sound=true; G.UI.prefs.quality='high'; G.Audio.ctx=null; G.Audio.wet=null")
    bad = ev(page, "['nav','sheet','whoosh','flash','flashes','walkout','trophy','reveal','farewell','stamp','tap','fanfare'].filter(n=>{try{G.Audio.play(n);return false}catch(e){return true}})")
    check(bad == [], 'كل الأصوات (الجديدة والقديمة) تعمل دون استثناء %s' % bad)
    ev(page, "G.Audio.crowd(true)"); page.wait_for_timeout(200); ev(page, "G.Audio.crowd(false)")
    check(ev(page, "!!G.Audio.ctx") is False or ev(page, "!!G.Audio.wet") is True, 'صدى الاستاد مفعّل بالجودة العالية')
    ev(page, "G.UI.prefs.quality='low'; G.Audio.ctx=null; G.Audio.wet=null; G.Audio.play('trophy')")
    check(ev(page, "!G.Audio.wet"), 'الجودة المنخفضة بلا صدى')
    check(not errors, 'لا أخطاء JS: %s' % errors[:3])
    b.close()
finish()
